"use client";

/** A tab strip over sections that must all stay alive.
 *
 * **Every panel is rendered and the inactive ones are hidden, rather
 * than only the active one being mounted.** That is the whole reason
 * this component exists instead of a ternary in the page:
 *
 * - The episode viewer fetches a trace per candidate, holds a
 *   `setInterval` while a replay is playing, and remembers which episode
 *   the reader picked, how the 2.5D camera is turned and where the
 *   scrubber is. Unmounting it throws all of that away, so leaving the
 *   tab and coming back would re-download two traces and restart the
 *   replay from zero — a reader flipping to the evidence to check a
 *   number and back would lose the moment they were looking at.
 * - The advisory panels below hold answers that cost a model call and
 *   several seconds to fetch, and there is no cache behind them. Losing
 *   one on a tab switch means paying for it again.
 * - Every panel mounts on first render, exactly as it did when the page
 *   was one long column, so nothing about *when* anything is fetched
 *   changes with this layout.
 *
 * The cost is that the whole page is still built on load. It was
 * already; this changes what is on screen, not what is constructed.
 *
 * Hidden with the `hidden` attribute rather than a class, because
 * `hidden` also takes the panel out of the accessibility tree and out of
 * find-in-page — a `visibility: hidden` panel is still four screens of
 * text a screen reader walks through.
 */

import { useRef, type KeyboardEvent, type ReactNode } from "react";

import { tabAfterKey } from "@/lib/decisionTabs";
import { useTranslation } from "@/lib/i18n";

export interface DecisionTabSpec {
  id: string;
  /** Translation key for the tab's label. */
  labelKey: string;
  content: ReactNode;
}

export function DecisionTabs({
  tabs,
  active,
  onSelect,
  labelKey,
}: {
  tabs: DecisionTabSpec[];
  active: string;
  onSelect: (id: string) => void;
  /** Translation key naming the strip, for a screen reader. */
  labelKey: string;
}) {
  const { t } = useTranslation();
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);

  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const next = tabAfterKey(event.key, index, tabs.length);
    if (next === null) return;
    // Arrows scroll the page by default, and `Home`/`End` jump it to an
    // end — either would move the reader away from the strip they are
    // steering with.
    event.preventDefault();
    onSelect(tabs[next].id);
    // **Selection follows focus, and focus follows the arrow.** A roving
    // `tabIndex` means only the selected tab is a tab stop, so without
    // this the focus ring would stay on a button that is no longer the
    // one in tab order.
    buttons.current[next]?.focus();
  };

  return (
    <div className="decision-tabs">
      <div className="decision-tablist" role="tablist" aria-label={t(labelKey)}>
        {tabs.map((tab, index) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            id={`decision-tab-${tab.id}`}
            ref={(node) => {
              buttons.current[index] = node;
            }}
            className={`decision-tab${tab.id === active ? " is-active" : ""}`}
            aria-selected={tab.id === active}
            aria-controls={`decision-tabpanel-${tab.id}`}
            tabIndex={tab.id === active ? 0 : -1}
            onKeyDown={(event) => onKeyDown(event, index)}
            onClick={() => onSelect(tab.id)}
          >
            {t(tab.labelKey)}
          </button>
        ))}
      </div>
      {tabs.map((tab) => (
        <div
          key={tab.id}
          role="tabpanel"
          id={`decision-tabpanel-${tab.id}`}
          aria-labelledby={`decision-tab-${tab.id}`}
          className="decision-tabpanel"
          hidden={tab.id !== active}
        >
          {tab.content}
        </div>
      ))}
    </div>
  );
}

"use client";

/** English ↔ Tiếng Việt.
 *
 * Each language is named *in itself* — "Tiếng Việt", not "Vietnamese".
 * Someone who cannot read the current language still has to be able to
 * find their own, which is the one case a language switcher exists for.
 *
 * Changing it reloads the route. The locale is a cookie the server reads
 * while rendering, so a refresh is what makes the server agree; without
 * it the shell would switch and any server-rendered text would not.
 */

import { useRouter } from "next/navigation";

import { Menu } from "./Menu";
import { LOCALES, localeStore, useTranslation, type Locale } from "@/lib/i18n";

export function LanguageSwitcher() {
  const { t, locale } = useTranslation();
  const router = useRouter();

  return (
    <Menu<Locale>
      label={t("language.label")}
      tooltip={t("language.switch", { current: t(`language.${locale}`) })}
      icon="globe"
      buttonLabel={locale.toUpperCase()}
      value={locale}
      onSelect={(next) => {
        if (next === locale) return;
        localeStore.set(next);
        router.refresh();
      }}
      choices={LOCALES.map((value) => ({ value, label: t(`language.${value}`) }))}
    />
  );
}

"use client";

/** English and Vietnamese in the browser: the store, the context, the hook.
 *
 * The dictionaries and the lookup itself are in `./shared.ts`, which is
 * *not* a client module — the server layout reads the locale cookie
 * while rendering, and that is what removes the flash of the wrong
 * language. Re-exports below are for components, which are all clients.
 *
 * The locale lives in a **cookie**, not localStorage, for the same
 * reason: a cookie is the only preference the server can see while it
 * renders.
 *
 * Missing keys fall back to English rather than throwing or rendering
 * blank: a half-translated screen is usable, an empty one is not.
 */

import { createContext, useContext } from "react";

import {
  DEFAULT_LOCALE,
  DICTIONARIES,
  LOCALES,
  LOCALE_COOKIE,
  localeFromCookie,
  translate,
  type Locale,
  type Vars,
} from "./shared";
import { createPersistedStore, readCookie, usePersisted } from "../persisted";

export {
  DEFAULT_LOCALE,
  DICTIONARIES,
  LOCALES,
  LOCALE_COOKIE,
  detectLocale,
  localeFromCookie,
  translate,
} from "./shared";
export type { Dictionary, Locale, Vars } from "./shared";

export const localeStore = createPersistedStore<Locale>({
  key: LOCALE_COOKIE,
  fallback: DEFAULT_LOCALE,
  allowed: LOCALES,
  backend: "cookie",
  onChange: (locale) => {
    if (typeof document !== "undefined") document.documentElement.lang = locale;
  },
});

/**
 * The locale the server rendered with.
 *
 * Provided by the root layout, which read the cookie. The client store
 * cannot be trusted for the *first* render — it would read the cookie
 * itself and could disagree with the server's HTML — so the context
 * value wins until the user actually changes the language.
 */
export const LocaleContext = createContext<Locale>(DEFAULT_LOCALE);

export interface Translator {
  locale: Locale;
  t: (key: string, vars?: Vars) => string;
}

export function useTranslation(): Translator {
  const locale = useContext(LocaleContext);
  const dictionary = DICTIONARIES[locale] ?? DICTIONARIES[DEFAULT_LOCALE];
  return {
    locale,
    t: (key: string, vars?: Vars) =>
      translate(dictionary, DICTIONARIES[DEFAULT_LOCALE], key, vars),
  };
}

/** Subscribe to locale changes. Only the provider needs this. */
export function useStoredLocale(): Locale {
  return usePersisted(localeStore);
}

/** Read the current locale outside React (before hydration). */
export function currentLocale(): Locale {
  return localeFromCookie(readCookie(LOCALE_COOKIE));
}

