  padding-top: var(--space-4);
  border-top: 1px solid var(--border);
}

.guide-prevnext a {
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-decoration: none;
  color: var(--text);
}

.guide-prevnext a span {
  font-size: 0.78rem;
  color: var(--text-muted);
}

.guide-next {
  text-align: right;
  margin-left: auto;
}

.guide-callout {
  margin: var(--space-4) 0;
  padding: var(--space-3) var(--space-4);
  border-left: 3px solid var(--border);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  background: var(--surface-2);
}

.guide-callout > :first-child { margin-top: 0; }
.guide-callout > :last-child { margin-bottom: 0; }

/* Three kinds, three consequences: context, something that will go
   wrong, and the guide admitting the system cannot do this yet. */
.guide-callout-trap { border-left-color: var(--warning, var(--accent)); }
.guide-callout-missing { border-left-color: var(--danger, var(--accent)); }

.guide-applink {
  display: inline-block;
  font-weight: 600;
}

/* The skeleton is given a height so the page does not grow under the
   reader when the article's chunk lands. */
.guide-skeleton {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  max-width: 46rem;
}

.guide-skeleton-line {
  height: 1rem;
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}

.guide-skeleton-line:nth-child(3n) { width: 82%; }
.guide-skeleton-line:nth-child(4n) { width: 64%; }

.sidebar-utility {
  margin-top: auto;
  padding-top: var(--space-3);
  border-top: 1px solid var(--border);
}

@media (max-width: 900px) {
  .guide-shell { grid-template-columns: minmax(0, 1fr); }
  .guide-rail { position: static; }
}
