"use client";

/** Tabs inside an article, addressable by the URL.
 *
 * Wraps `DecisionTabs` rather than repeating it: that component already
 * carries the keyboard contract this needs — roving `tabIndex`, arrows
 * and Home/End, selection following focus — and a second implementation
 * of a tab strip is a second set of those rules to drift.
 *
 * What is added here is the address. `/guide/gates#g2` has to open on
 * G2, and moving between tabs has to leave the browser's Back button
 * meaning something, so the hash is the state:
 *
 * - **The hash chooses the tab, and never steals focus.** A deep link or
 *   a reload is somebody arriving, not somebody asking to be moved; a
 *   page that grabs the caret on load takes it away from whatever they
 *   were doing. Focus-on-open belongs to a search result, which is a
 *   deliberate act — and is not wired here.
 * - **A hash naming nothing falls to the first tab**, rather than to a
 *   blank panel. A stale link should show the article, not an accusation.
 * - **`pushState`, not `replaceState`**, so Back walks the tabs the
 *   reader actually opened.
 *
 * Titles arrive as text, not translation keys: they live in the manifest
 * in both languages, which is what the `label` half of `DecisionTabs`
 * was widened for.
 */

import { useEffect, useState, type ReactNode } from "react";

import { DecisionTabs } from "@/components/DecisionTabs";
import { articleBySlug } from "../../../content/guide/manifest";
import { useTranslation } from "@/lib/i18n";

export function GuideTabs({
  slug,
  children,
}: {
  /** The article these tabs belong to; its manifest entry names them. */
  slug: string;
  /** One child per tab, in the manifest's order. */
  children: ReactNode[];
}) {
  const { locale, t } = useTranslation();
  const article = articleBySlug(slug);
  const tabs = article?.tabs ?? [];
  const [active, setActive] = useState(tabs[0]?.id ?? "");

  useEffect(() => {
    const fromHash = () => {
      const id = window.location.hash.slice(1);
      if (tabs.some((tab) => tab.id === id)) setActive(id);
    };
    fromHash();
    window.addEventListener("hashchange", fromHash);
    return () => window.removeEventListener("hashchange", fromHash);
    // `tabs` is derived from a module-level constant keyed by `slug`;
    // listing it would re-subscribe on every render for no change.
  }, [slug]); // eslint-disable-line react-hooks/exhaustive-deps

  if (tabs.length === 0) return null;

  return (
    <DecisionTabs
      tabs={tabs.map((tab, index) => ({
        id: tab.id,
        label: tab.title[locale],
        content: children[index] ?? null,
      }))}
      active={active}
      onSelect={(id) => {
        setActive(id);
        window.history.pushState(null, "", `#${id}`);
      }}
      label={t("guide.tabs", { article: article?.title[locale] ?? "" })}
    />
  );
}
