import re, sys
from pathlib import Path

def in_string_hits(path):
    """Line numbers where an em dash sits inside a string literal.

    Tracks block comments and line comments so a docstring full of em
    dashes - which this repo has a great many of - is not mistaken for
    text that reaches a screen.
    """
    src = Path(path).read_text(encoding="utf-8")
    hits, block = [], False
    for n, line in enumerate(src.splitlines(), 1):
        if "—" not in line and not block:
            if "/*" in line and "*/" not in line:
                block = True
            continue
        i, quote, out = 0, None, []
        if block:
            if "*/" in line:
                i = line.index("*/") + 2
                block = False
            else:
                continue
        while i < len(line):
            c = line[i]
            if quote:
                if c == "\\":
                    i += 2; continue
                if c == quote:
                    quote = None
                elif c == "—":
                    out.append(i)
            else:
                if c in "\"'`":
                    quote = c
                elif line.startswith("//", i):
                    break
                elif line.startswith("/*", i):
                    if "*/" in line[i + 2:]:
                        i = line.index("*/", i + 2) + 2; continue
                    block = True; break
            i += 1
        if out:
            hits.append((n, line.strip()[:100]))
    return hits

total = 0
for path in sorted(Path(p) for p in sys.argv[1:]):
    hits = in_string_hits(path)
    if hits:
        total += len(hits)
        print(f"\n{path}  ({len(hits)} line(s))")
        for n, text in hits[:4]:
            print(f"  {n}: {text}")
        if len(hits) > 4:
            print(f"  … {len(hits) - 4} more")
