from pathlib import Path

def sweep_code(path):
    """Replace em dashes inside string literals, never inside comments.

    A literal whose entire content is one em dash is left alone: there it
    is not punctuation but the glyph for "no value", and a lone hyphen in
    a column of signed numbers reads as a minus sign.
    """
    src = Path(path).read_text(encoding="utf-8")
    out, block, changed = [], False, 0
    for line in src.splitlines(keepends=True):
        body = line
        i, quote, start, chars = 0, None, 0, list(line)
        if block:
            if "*/" in line:
                i = line.index("*/") + 2
                block = False
            else:
                out.append(line); continue
        while i < len(chars):
            c = chars[i]
            if quote:
                if c == "\\":
                    i += 2; continue
                if c == quote:
                    content = "".join(chars[start:i])
                    if content.strip() != "—":
                        for j in range(start, i):
                            if chars[j] == "—":
