                elif line.startswith("/*", i):
                    if "*/" in line[i + 2:]:
                        i = line.index("*/", i + 2) + 2; continue
                    block = True; break
            i += 1
        out.append("".join(chars))
    if changed:
        Path(path).write_text("".join(out), encoding="utf-8")
    return changed

